/**
 * The MHPCO price list: the office's catalogue of what it will insure and what
 * each kind of thing costs. It answers the questions of item *kind* -- is this a
 * main item or a component, what is its tariff row -- and nothing about
 * underwriting policy or settlement. A new item type revises this table alone.
 */

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

/**
 * The price list prices each main item type by its own tariff row, but prices
 * every component by one rule: 25 G per component, whatever its kind.
 */
const MAIN_ITEM_BASE_PREMIUM: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};
const MAIN_ITEM_INSURANCE_VALUE: Record<string, number> = {
  sword: 1000,
  amulet: 600,
  staff: 800,
  potion: 400,
};
const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
const COMPONENT_INSURANCE_VALUE = 250;

export const COMPONENT_BASE_PREMIUM = 25;

export function isComponent(type: string): boolean {
  return COMPONENT_TYPES.has(type);
}

/**
 * The MHPCO insures nothing that is absent from its price list, so an unlisted
 * type is refused rather than priced. This is one underwriting decision, not one
 * per column: whichever figure is being looked up, a type without a tariff row is
 * a type the office does not insure. Every column reads its row through here so
 * that the refusal -- and one day the shape the CLI must report it as -- is
 * revised in a single place.
 */
function listedRow(table: Record<string, number>, type: string): number {
  const figure = table[type];
  if (figure === undefined) {
    throw new Error(`The MHPCO does not insure items of type "${type}"`);
  }
  return figure;
}

/**
 * The tariff row a main item is priced from. Components have no row of their own.
 */
export function mainItemBasePremium(type: string): number {
  return listedRow(MAIN_ITEM_BASE_PREMIUM, type);
}

/**
 * What the MHPCO insures an item for. Every item is insured on its own value --
 * the block discount is a premium concession and never lowers the insured sum.
 */
export function insuranceValue(type: string): number {
  if (isComponent(type)) {
    return COMPONENT_INSURANCE_VALUE;
  }
  return listedRow(MAIN_ITEM_INSURANCE_VALUE, type);
}

/**
 * What a set of items insures for. The price list adds insurance values item by
 * item, with no group rate of any kind: 3 runes insure for 750 G even though the
 * same 3 runes are *premiumed* as a 60 G block. The block is a premium
 * concession, and this is the line that keeps it out of the insured sum.
 */
export function insuranceValueOf(items: Item[]): number {
  return items.reduce((total, item) => total + insuranceValue(item.type), 0);
}
---CLAIM---
/**
 * The MHPCO claim office: it settles a damage report against an open policy. It
 * answers what the office pays for a reported damage -- what the damage is worth
 * under the policy's clauses, and what the office's settlement conventions then
 * deduct from it. It knows nothing about what a policy costs to take out; that
 * is the quote's business.
 */

import { insuranceValueOf, type Item } from "./price-list.js";

export interface Damage {
  itemType: string;
  amount: number;
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export interface Policy {
  items: Item[];
  cap: number;
}

export interface ClaimResult {
  payout: number;
}

const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;

/** The sum a policy insures, read off the price list for the items it covers. */
export function insuranceSum(policy: Policy): number {
  return insuranceValueOf(policy.items);
}

/**
 * Opening a policy fixes the cover it grants: the office caps its total payout at
 * twice the insurance sum of the items presented. The cap is fixed from the
 * items' own insurance values, so no premium modifier can raise it.
 */
export function openPolicy(items: Item[]): Policy {
  return { items, cap: CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceValueOf(items) };
}

const DEDUCTIBLE_PER_DAMAGE = 100;

const HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
const HALF_REIMBURSEMENT_PERCENT = 50;
const PERCENT = 100;

/**
 * The claim office's enchantment threshold, deliberately its own rule. The price
 * list also reads an enchantment level off an item, but for an unrelated purpose
 * and at an unrelated level (>= 5, a premium risk surcharge). The two thresholds
 * share no cause: moving one does not move the other, which is why the office
 * keeps them apart rather than naming them alike.
 */
function qualifiesForHalfReimbursement(item: Item): boolean {
  return (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL;
}

/**
 * What a reported damage is worth under the policy's clauses. A deeply enchanted
 * item is reimbursed at half its damage; an item no clause speaks to is
 * reimbursed in full.
 *
 * The office also names a dragon-material clause, and it is deliberately absent
 * here rather than overlooked. That clause grants full reimbursement -- which is
 * already what an item no clause speaks to receives -- so it can only change an
 * outcome by overriding a *reducing* clause. Against the sole reducing clause the
 * office has, the half-reimbursement rule, it does not: a dragon-material sword
 * at enchantment 8 or 9 is valued at half, not in full. So under every rule the
 * office currently holds, a dragon branch would return exactly what this fallback
 * returns. Writing it would not encode the clause; it would encode a precedence
 * decision between dragon material and some future reducing clause, and the
 * office has not made that decision. When a reducing clause appears that dragon
 * material is meant to outrank, that precedence becomes observable and belongs
 * here then.
 */
function reimbursementFor(damage: Damage, item: Item): number {
  if (qualifiesForHalfReimbursement(item)) {
    return (damage.amount * HALF_REIMBURSEMENT_PERCENT) / PERCENT;
  }
  return damage.amount;
}

/** The insured item a reported damage refers to, found by its type. */
function damagedItem(policy: Policy, damage: Damage): Item {
  const item = policy.items.find((insured) => insured.type === damage.itemType);
  if (item === undefined) {
    throw new Error(`The policy does not cover an item of type "${damage.itemType}"`);
  }
  return item;
}

/**
 * Settling turns a reimbursement into the sum actually paid. The deductible is
 * the MHPCO's settlement convention, not a clause: it is charged per damage
 * event, after the reimbursement is valued, and never turns a payout negative.
 */
function settleReimbursement(reimbursement: number): number {
  return Math.max(reimbursement - DEDUCTIBLE_PER_DAMAGE, 0);
}

/**
 * The office's whole decision about one reported damage: find the item it refers
 * to, value it under the policy's clauses, then settle that reimbursement. What
 * the office then does with several such sums -- adding them up, and one day
 * charging them against the policy's remaining cap -- is the claim's business,
 * not this one's.
 */
function settleDamage(policy: Policy, damage: Damage): number {
  return settleReimbursement(reimbursementFor(damage, damagedItem(policy, damage)));
}

export function claim(policy: Policy, incident: Incident): ClaimResult {
  const payout = incident.damages.reduce(
    (total, damage) => total + settleDamage(policy, damage),
    0,
  );
  return { payout };
}

